import fs from 'fs';
import path from 'path';
import { HubDiscovery } from '../services/HubDiscovery';
import { ProjectRegistry } from '../services/ProjectRegistry';
import { currentLibraryRoot } from '../services/ProjectLibrary';
import { ensureHub } from '../library/HubClient';
import { readHandshake, isPidAlive } from './serverHandshake';
import { serverVersionInfo } from './serverVersion';
import {
  ensureProjectRuntime,
  type ProjectRuntimeDependencies,
} from './commands/open';
import { isCommandResult, parseCommandContext } from './commands/shared';
import type { CliIO } from './io';
import { errorMessage } from '../utils/errorMessage';

interface RuntimeSynchronization {
  wasCoordinatorRestarted: boolean;
  projectsRestarted: number;
  failures: Array<{ projectPath?: string; message: string }>;
}
interface SynchronizationOptions {
  args: string[];
  io: CliIO;
  env?: NodeJS.ProcessEnv;
  runtimeDependencies?: ProjectRuntimeDependencies;
}

const flagValue = (args: string[], flag: string): string | undefined => {
  const index = args.indexOf(flag);
  return index >= 0
    ? args[index + 1]
    : args.find((arg) => arg.startsWith(`${flag}=`))?.slice(flag.length + 1);
};

export const synchronizeRuntimes = async ({
  args,
  io,
  env = process.env,
  runtimeDependencies,
}: SynchronizationOptions): Promise<RuntimeSynchronization> => {
  const result: RuntimeSynchronization = {
    wasCoordinatorRestarted: false,
    projectsRestarted: 0,
    failures: [],
  };
  const root = currentLibraryRoot(env);
  let registry: ProjectRegistry | undefined;
  let discovery: HubDiscovery | undefined;
  try {
    registry = await ProjectRegistry.open(root);
    discovery = await HubDiscovery.open(root);
    const coordinator = discovery.read();
    if (coordinator && isPidAlive(coordinator.pid)) {
      try {
        await ensureHub({ root, env, isSourceSyncAllowed: args[0] !== 'mcp' });
        result.wasCoordinatorRestarted =
          discovery.read()?.pid !== coordinator.pid;
      } catch (error) {
        result.failures.push({
          message: errorMessage(error),
        });
      }
    }
    const candidates = new Set([
      path.resolve(flagValue(args, '--project') ?? process.cwd()),
      ...registry
        .list()
        .map((project) => project.id)
        .flatMap(registry.historyRoots.bind(registry)),
    ]);
    for (const candidate of candidates) {
      if (!fs.existsSync(candidate)) continue;
      let projectPath = candidate;
      try {
        projectPath = fs.realpathSync(candidate);
        const handshake = readHandshake(projectPath);
        if (
          !handshake ||
          !isPidAlive(handshake.pid) ||
          !serverVersionInfo(handshake).staleServer
        )
          continue;
        const handoffArgs = [
          '--caller-agent',
          '--caller-model',
          '--caller-session',
          '--handoff',
        ].flatMap((flag) => {
          const value = flagValue(args, flag);
          return value ? [flag, value] : [];
        });
        const context = parseCommandContext('open', [
          '--project',
          projectPath,
          ...handoffArgs,
        ]);
        if (isCommandResult(context))
          throw new Error('Could not resolve the project upgrade context.');
        const opened = await ensureProjectRuntime(context, io, {
          ...runtimeDependencies,
          env,
        });
        if (!opened.envelope.ok) throw new Error(opened.envelope.error.message);
        const current = readHandshake(projectPath);
        if (!current || serverVersionInfo(current).staleServer)
          throw new Error('The replacement server is still outdated.');
        result.projectsRestarted += 1;
      } catch (error) {
        result.failures.push({
          projectPath,
          message: errorMessage(error),
        });
      }
    }
  } catch (error) {
    result.failures.push({
      message: errorMessage(error),
    });
  } finally {
    discovery?.close();
    registry?.close();
  }
  return result;
};
